"""
Online Stock Provider Adapter and Story-Driven Retrieval Engine (ADR-009).
Implements hard constraint filtering, rights eligibility (ELIGIBLE/UNKNOWN/DISALLOWED),
preview-to-acquired asset reconciliation, and story-driven candidate ranking.
"""
import os
